import{_ as n,C as t,o,c as s,E as a,a2 as d}from"./chunks/framework.BOeh4kYD.js";const l="/joinwell52/assets/control-intent-20260917/quota-behind-error-code.figure.en.svg",b=JSON.parse('{"title":"The quota is exhausted. Why is the agent still retrying?","description":"","frontmatter":{"schema":"publication-candidate-article/v2","title":"The quota is exhausted. Why is the agent still retrying?","date":"2026-09-17","published_date":"2026-09-17","column":"open-source-engineering","category":"daily","article_type":"experiment-report","edition":"research-center","research_question":"The quota is exhausted. Why is the agent still retrying?","summary":"A provider can name the reset time while a recovery system sees only a failed turn. We trace the same message through two versions of the classifier.","cover":"/assets/control-intent-20260917/quota-behind-error-code.cover-v1.png","language":"en","lifecycle":"Published","publication_authorized":true,"evidence_status":"Bounded original-code experiments; scope in article","pageClass":"control-intent-article"},"headers":[],"relativePath":"en/engineering/2026-09-17-quota-behind-error-code.md","filePath":"en/engineering/2026-09-17-quota-behind-error-code.md","lastUpdated":1789614884000}'),h={name:"en/engineering/2026-09-17-quota-behind-error-code.md"};function c(p,e,u,m,g,f){const i=t("ArticleCover"),r=t("ArticleTableScroll");return o(),s("div",null,[a(i,{image:"/assets/control-intent-20260917/quota-behind-error-code.cover-v1.png",kicker:"Open-source engineering · Experimental research",title:"The quota is exhausted. Why is the agent still retrying?",summary:"A provider can name the reset time while a recovery system sees only a failed turn. We trace the same message through two versions of the classifier.",version:"2026-09-17",languageHref:"/zh/engineering/2026-09-17-quota-behind-error-code",languageLabel:"中文"}),a(r,{language:"en"}),e[0]||(e[0]=d('<h1 id="the-quota-is-exhausted-why-is-the-agent-still-retrying" tabindex="-1">The quota is exhausted. Why is the agent still retrying? <a class="header-anchor" href="#the-quota-is-exhausted-why-is-the-agent-still-retrying" aria-label="Permalink to &quot;The quota is exhausted. Why is the agent still retrying?&quot;">​</a></h1><p>The agent stops. Its provider says the quota is exhausted and gives a reset time for later that evening.</p><p>Then the task retries. The counter rises; the work goes nowhere. Which part of the message did the system fail to understand?</p><p>One possibility is that the provider supplied a cause, while the program recorded only “this step failed.” “The warehouse is closed today” became “delivery failed,” so another delivery was scheduled.</p><h2 id="where-did-the-cause-get-lost" tabindex="-1">Where did the cause get lost? <a class="header-anchor" href="#where-did-the-cause-get-lost" aria-label="Permalink to &quot;Where did the cause get lost?&quot;">​</a></h2><p>The source is <a href="https://github.com/paperclipai/paperclip/pull/13549" target="_blank" rel="noreferrer">Paperclip #13549</a>, by electrumnz. Paperclip coordinates ongoing AI work, including recovery after failures.</p><p>The author reported 320 quota-related terminal runs in a production review, 186 carrying retry links, while quota reasons were missing. That is upstream evidence; we did not access the production data. It caught our attention because trying again may help a temporary network failure, while repeatedly trying before quota resets may achieve nothing.</p><p>To choose a next step, the program must first identify the cause. The patch adds a previously missed entry point: when a message arrives under a failed-turn error code, the classifier also checks it for quota information.</p><p>The question is therefore not just whether the provider explained the failure. <strong>Did that explanation reach the code responsible for producing a waiting time?</strong></p><h2 id="send-the-same-sentence-through-again" tabindex="-1">Send the same sentence through again <a class="header-anchor" href="#send-the-same-sentence-through-again" aria-label="Permalink to &quot;Send the same sentence through again&quot;">​</a></h2><p>We extracted the original classification code and parsing helpers from both revisions and supplied the same nine inputs. One described exhausted quota and specified when it would reset.</p><table tabindex="0"><thead><tr><th>Input</th><th>Before</th><th>Candidate</th></tr></thead><tbody><tr><td>Quota message with a reset time, through the failed-turn entry point</td><td>No classification</td><td>Quota recognized; reset time calculated from the message</td></tr><tr><td>Quota message without a reset time</td><td>No classification</td><td>Quota recognized; default one-hour wait</td></tr><tr><td>Ordinary socket failure</td><td>No classification</td><td>Still no classification</td></tr><tr><td>Missing key through the existing adapter-failure entry point</td><td>Configuration incomplete</td><td>Still configuration incomplete</td></tr></tbody></table><p>Both of the first two rows produce a time, but for different reasons. One comes from the provider&#39;s message; the other is a fallback used when information is missing.</p><p>That distinction matters to someone waiting. “Try again at this time” can sound like a promise that service will be available. <strong>A default one-hour delay says when the program proposes to try again; it makes no such promise about the provider.</strong></p><p><img src="'+l+'" alt="Similar-looking retry times can have different foundations"></p><p><em>Figure 1. Source: author illustration from the two original classifiers. Exact timestamps and timezone conversion remain in the experimental supplement.</em></p><p>This verifies what the classifier returns. Whether the program arranging the next execution actually waits accordingly needs a further test. The table alone cannot establish that the complete retry problem is solved.</p><h2 id="a-keyword-can-appear-in-a-denial" tabindex="-1">A keyword can appear in a denial <a class="header-anchor" href="#a-keyword-can-appear-in-a-denial" aria-label="Permalink to &quot;A keyword can appear in a denial&quot;">​</a></h2><p>We deliberately supplied this sentence:</p><blockquote><p>No quota exceeded. Socket failed.</p></blockquote><p>The candidate still classified it as a quota problem and returned the default one-hour wait.</p><p>This was a constructed counterexample; we have no evidence that a real provider sends that wording. It demonstrates a limit of keyword matching: recognizing a word does not necessarily establish what the sentence means.</p><p>Another input supplied an invalid timezone and also triggered the fallback. An equally precise-looking time can therefore come from successful parsing or a backup rule. Preserving that distinction helps explain why the program waits as it does.</p><h2 id="a-timestamp-needs-an-explanation" tabindex="-1">A timestamp needs an explanation <a class="header-anchor" href="#a-timestamp-needs-an-explanation" aria-label="Permalink to &quot;A timestamp needs an explanation&quot;">​</a></h2><p>A useful next direction is for provider adapters to pass an explicit cause and reset time, reducing reliance on prose. When inference or fallback is needed, its basis should remain available. That is a design direction; this experiment tested only the classifiers.</p><p>Users can help examine the next part of the chain. Save the original message and time, then record whether retries keep accumulating and whether work resumes when expected. Those observations help connect “cause recognized” to “execution actually waited.”</p><p><strong>When a tool says “wait until this time,” can it also tell you whether the provider supplied that time or the program estimated it?</strong></p><details><summary>Revisions and experimental boundary</summary><h3 id="original-detailed-comparison" tabindex="-1">Original detailed comparison <a class="header-anchor" href="#original-detailed-comparison" aria-label="Permalink to &quot;Original detailed comparison&quot;">​</a></h3><p>The experiment clock was September 16, 2026, 04:50 UTC. The message specified 21:20 Pacific/Auckland, parsed as 09:20 UTC. Without a reset time, the one-hour fallback yielded 05:50 UTC. The PR was open at our source read; that timestamped status does not claim it remains unchanged.</p><p>The newly included entry point is <code>acpx_turn_failed</code>. The output field <code>parsedResetTime</code> distinguishes a parsed reset from a fallback. “No classification” means this function returned null; it does not establish that all downstream handling immediately retries.</p><table tabindex="0"><thead><tr><th>Input</th><th>Before</th><th>Candidate</th></tr></thead><tbody><tr><td>Quota message through the failed-turn entry point</td><td>No classification</td><td>Provider quota; retry at 09:20 UTC</td></tr><tr><td>Quota message without a reset time</td><td>No classification</td><td>Provider quota; retry at 05:50 UTC</td></tr><tr><td>Ordinary socket failure</td><td>No classification</td><td>Still no classification</td></tr><tr><td>Missing key through the existing adapter-failure entry point</td><td>Configuration incomplete</td><td>Still configuration incomplete</td></tr></tbody></table><p>Base: <code>d0b67bfe71277f5a5ad21c7a7b6cb7af09e2ccca</code>. Candidate: <code>688c994a95d6c447816c50b14e30745d8ea9e855</code>. Checked source anchors extract the original classifier block and its original parsing helpers. Nine inputs across two versions produce 18 observations, not 18 live provider calls.</p><p>Additional inputs cover a structured retryNotBefore value yielding 12:00 UTC, an unknown error code, an invalid timezone, and missing-key messages entering through different error codes. The negated sentence is deliberately synthetic.</p><p>We did not run the recovery scheduler, database scan, production account or model. <a href="https://github.com/joinwell52-AI/joinwell52/tree/main/research/manual-runs/2026-09-17-control-intent" target="_blank" rel="noreferrer">Results and reproduction scripts</a>. The experiment does not establish the same error path or quota-retry defect in CodeFlowMu.</p></details><p><a href="https://github.com/joinwell52-AI/joinwell52" target="_blank" rel="noreferrer">Research repository</a></p>',29))])}const w=n(h,[["render",c]]);export{b as __pageData,w as default};
